INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Závěrečný kvíz — Celý SQL kurz', '<p>Závěrečný test pokrývající všechny sekce kurzu SQL & Databáze.</p>', 'final_quiz', 35, 200, 25);

SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Co vrací SELECT COUNT(*) FROM users?', 'Počet sloupců v tabulce users', 'Počet všech řádků v tabulce users', 'První ID v tabulce', 'Počet non-NULL sloupců', 'b', 'COUNT(*) počítá všechny řádky v tabulce včetně těch s NULL hodnotami.', 1),
(@qfin, 'Jaký je rozdíl mezi LEFT JOIN a INNER JOIN?', 'LEFT JOIN vrací všechny řádky z levé tabulky, INNER jen shody', 'Jsou stejné', 'LEFT JOIN je rychlejší', 'INNER JOIN vrací více řádků', 'a', 'LEFT JOIN zachová všechny řádky z levé tabulky (doplní NULL pro chybějící shody), INNER JOIN vrátí jen řádky se shodou v obou tabulkách.', 2),
(@qfin, 'Co dělá HAVING ve spojení s GROUP BY?', 'Filtruje řádky před seskupením', 'Filtruje skupiny po agregaci', 'Seřadí výsledky', 'Omezí počet řádků', 'b', 'HAVING filtruje skupiny po GROUP BY agregaci, zatímco WHERE filtruje jednotlivé řádky před seskupením.', 3),
(@qfin, 'Co je correlated subquery?', 'Subquery nezávislá na vnějším dotazu', 'Subquery, která odkazuje na sloupce z vnějšího dotazu', 'Subquery ve FROM klauzuli', 'Rekurzivní CTE', 'b', 'Correlated subquery se spustí pro každý řádek vnějšího dotazu, protože odkazuje na jeho sloupce.', 4),
(@qfin, 'K čemu slouží WITH (CTE)?', 'K vytvoření dočasné pojmenované sady výsledků', 'K definování proměnných', 'K transakci', 'K vytvoření indexu', 'a', 'CTE (Common Table Expression) definuje pojmenovaný dočasný výsledek, který zlepšuje čitelnost složitých dotazů.', 5),
(@qfin, 'Co vrací RANK() OVER (ORDER BY xp DESC)?', 'Unikátní číslo pro každý řádek', 'Pořadí se stejnými hodnotami na stejné pozici (s mezerami)', 'Počet řádků', 'Průměrné XP', 'b', 'RANK() přiřadí stejné pořadí řádkům se stejnou hodnotou, následující pořadí se přeskočí (1,2,2,4).', 6),
(@qfin, 'Co je covering index?', 'Index, který pokrývá všechny sloupce dotazu', 'Index na všechny tabulky', 'Index na primární klíč', 'Fulltext index', 'a', 'Covering index obsahuje všechny sloupce potřebné pro dotaz — databáze nemusí číst samotnou tabulku.', 7),
(@qfin, 'Jaký isolation level je výchozí v MariaDB?', 'READ UNCOMMITTED', 'READ COMMITTED', 'REPEATABLE READ', 'SERIALIZABLE', 'c', 'REPEATABLE READ je výchozí isolation level v MariaDB/MySQL — zaručuje konzistentní čtení v rámci transakce.', 8),
(@qfin, 'Co je SQL injection?', 'Chyba v SQL syntaxi', 'Útok vložením škodlivého SQL přes uživatelský vstup', 'Pomalý dotaz', 'Přetečení paměti', 'b', 'SQL injection je útok, kdy útočník vloží SQL kód přes neošetřený vstup — prevence jsou prepared statements.', 9),
(@qfin, 'Proč se v phpMyAdmin nedají přímo vytvářet stored procedures?', 'MariaDB je nepodporuje', 'phpMyAdmin nepodporuje DELIMITER příkaz', 'Chybí oprávnění', 'Procedures musí být v samostatném souboru', 'b', 'phpMyAdmin SQL konzole nepodporuje DELIMITER — workaround je GUI záložka Routines nebo CLI klient.', 10),
(@qfin, 'Co dělá mysqldump --single-transaction?', 'Zálohuje pouze jednu transakci', 'Vytvoří konzistentní zálohu InnoDB bez zamykání', 'Zálohuje jednu tabulku', 'Zkomprimuje zálohu', 'b', '--single-transaction použije snapshot transakce pro konzistentní zálohu bez blokování tabulek (pouze InnoDB).', 11),
(@qfin, 'Která normální forma odstraňuje tranzitivní závislosti?', '1NF', '2NF', '3NF', '4NF', 'c', '3NF (třetí normální forma) vyžaduje, že žádný neceločíslicový atribut nezávisí na jiném neceločíslicovém atributu — odstraňuje tranzitivní závislosti.', 12);


